int git_pkt_parse_network_packet(git_pkt **out, const char *line, size_t len) {
    git_pkt_ng *pkt;
    char *ref, *msg;
    size_t ref_len, msg_len;
    int ref_sep, msg_sep;

    if (len < 5)
        return -1;

    pkt = (git_pkt_ng *)malloc(sizeof(git_pkt_ng));
    if (!pkt)
        return -1;

    ref_sep = 0;
    for (size_t i = 0; i < len; i++) {
        if (line[i] == ':') {
            ref_sep = i;
            break;
        }
    }

    if (ref_sep == 0 || ref_sep == len - 1)
        goto error;

    ref_len = ref_sep;
    ref = (char *)malloc(ref_len + 1);
    if (!ref)
        goto error;

    memcpy(ref, line, ref_len);
    ref[ref_len] = '\0';

    pkt->ref = ref;

    msg_sep = 0;
    for (size_t i = ref_sep + 1; i < len; i++) {
        if (line[i] == '\0') {
            msg_sep = i;
            break;
        }
    }

    if (msg_sep == 0 || msg_sep == len - 1)
        goto error;

    msg_len = len - msg_sep - 1;
    msg = (char *)malloc(msg_len + 1);
    if (!msg)
        goto error;

    memcpy(msg, line + msg_sep + 1, msg_len);
    msg[msg_len] = '\0';

    pkt->msg = msg;

    *out = (git_pkt *)pkt;
    return 0;

