int parse_git_pkt(git_pkt **out, const char *line, size_t len) {
    git_pkt_ng *pkt;
    char *ref, *msg;
    size_t ref_len, msg_len;

    if (!line || len == 0) {
        return -1;
    }

    pkt = calloc(1, sizeof(git_pkt_ng));
    if (!pkt) {
        return -1;
    }

    // Assume the format is known and we can find a delimiter or split the line
    // Here, we will simulate parsing into ref and message
    char *newline_pos = strchr((char *)line, '\n');
    if (!newline_pos) {
        free(pkt);
        return -1;
    }

    ref_len = (size_t)(newline_pos - line);
    ref = strndup(line, ref_len);
    if (!ref) {
        free(pkt);
        return -1;
    }

    msg_len = len - ref_len - 1;
    if (msg_len > 0) {
        msg = strndup(newline_pos + 1, msg_len);
        if (!msg) {
            free(ref);
            free(pkt);
            return -1;
        }
    } else {
        msg = NULL;
    }

    pkt->ref = ref;
    pkt->msg = msg;
    pkt->type = GIT_PKT_REF;

    *out = (git_pkt *)pkt;
    return 0;
}

int git_pkt_parse(git_pkt **out, const char *line, size_t len) {
    git_pkt_ng *pkt;
    const char *ref_start, *msg_start;
    size_t ref_len, msg_len;

    if (!out || !line || len == 0) {
        return -1;
    }

    pkt = malloc(sizeof(git_pkt_ng));
    if (!pkt) {
        return -1;
    }

    pkt->ref = NULL;
    pkt->msg = NULL;

    /* Look for the end of the reference part */
    ref_start = line;
    const char *ref_end = memchr(line, '\0', len);
    if (!ref_end) {
        free(pkt);
        return -1;
    }

    ref_len = ref_end - ref_start;

    pkt->ref = strndup(ref_start, ref_len);
    if (!pkt->ref) {
        free(pkt);
        return -1;
    }

    /* Skip the null byte and look for message */
    msg_start = ref_end + 1;
    msg_len = len - (msg_start - line);

    if (msg_len > 0) {
        pkt->msg = strndup(msg_start, msg_len);
        if (!pkt->msg) {
            free(pkt->ref);
            free(pkt);
            return -1;
        }
    } else {
        pkt->msg = NULL;
    }

    *out = (git_pkt *)pkt;
    return 0;
}

