typedef struct git_pkt {
    char *ref;
    char *msg;
} git_pkt;

int parse_pkt_git_pkt(git_pkt **out, const char *line, size_t len) {
    git_pkt *pkt = NULL;

    // Allocate memory for the packet structure
    pkt = (git_pkt *)malloc(sizeof(git_pkt));
    if (!pkt)
        return -1;

    // Clear structure
    pkt->ref = NULL;
    pkt->msg = NULL;

    // Check for minimum required data length
    if (len < 5) {
        free(pkt);
        return -1;
    }

    // Assume the format is: <ref> NUL <msg> NUL
    const char *ref_start = line;
    const char *ref_end = memchr(line, '\0', len);
    if (!ref_end) {
        free(pkt);
        return -1;
    }

    // Parse reference
    pkt->ref = strndup(ref_start, ref_end - ref_start);
    if (!pkt->ref) {
        free(pkt);
        return -1;
    }

    // Move past reference and NUL
    const char *msg_start = ref_end + 1;
    if (msg_start >= line + len) {
        free(pkt->ref);
        free(pkt);
        return -1;
    }

    const char *msg_end = memchr(msg_start, '\0', len - (msg_start - line));
    if (!msg_end) {
        free(pkt->ref);
        free(pkt);
        return -1;
    }

    // Parse message
    pkt->msg = strndup(msg_start, msg_end - msg_start);
    if (!pkt->msg) {
        free(pkt->ref);
        free(pkt);
        return -1;
    }

    *out = pkt;
    return 0;
}
